const p = $json.body;
if (!p || p.eventType !== 'rental.approved' || p.consent !== true || !/^[1-9]\d{7,14}$/.test(p.to || '') || !/^ennour-contract-ATL-/.test(p.eventId || '') || typeof p.reference !== 'string') throw new Error('Demande invalide : acceptation admin, numéro et consentement obligatoires.');
if (!/^https:\/\/[^/@?#\s]+\/api\/contracts\/shared\/[A-Za-z0-9_-]+$/.test(p.contractUrl || '')) throw new Error('Une adresse HTTPS publique du contrat est requise.');
if (!/^\d+$/.test($json.phoneNumberId || '') || !/^v\d+\.\d+$/.test($json.graphVersion || '')) throw new Error('Complétez Phone Number ID et version Graph API dans Paramètres WhatsApp.');
if (!/^[a-z0-9_]+$/.test($json.templateName || '') || !/^[a-z]{2}(?:_[A-Z]{2})?$/.test($json.templateLanguage || '')) throw new Error('Vérifiez le nom et la langue du modèle approuvé par Meta.');
return [{json: {eventId:p.eventId, reference:p.reference, to:p.to, contractUrl:p.contractUrl,
 phoneNumberId:$json.phoneNumberId, graphVersion:$json.graphVersion, templateName:$json.templateName, templateLanguage:$json.templateLanguage}}];

const id = $json.messages?.[0]?.id;
if (typeof id !== 'string' || !id.startsWith('wamid.')) throw new Error('WhatsApp did not acknowledge the message');
return [{json:{status:'accepted',messageId:id}}];
